export function expandRpcFallbacks(primary: string, extra: string[] = []): string[] {
  const norm = (u: string) => u.trim().replace(/\/+$/, "");
  const seed = [primary, ...extra].map(norm).filter(Boolean);
  const seen = new Set<string>();
  const out: string[] = [];
  const push = (u: string) => {
    const n = norm(u);
    if (!n || seen.has(n)) return;
    seen.add(n);
    out.push(n);
  };
  for (const s of seed) {
    push(s);
    const mapped = RPC_FALLBACK_MAP[s];
    if (mapped) mapped.forEach(push);
  }
  return out.slice(0, 3);
}
